	@Test
	void storedBlankNodesCarryReferencesThroughSelectAndConstruct() throws Exception {
		servlet.destroy();
		servlet = newServlet("graph-max-query-length", "1000");
		var factory = repository.getValueFactory();
		try (var connection = repository.getConnection()) {
			connection.add(factory.createBNode("stored-graph-node"), factory.createIRI("urn:test:knows"),
					factory.createBNode("stored-graph-target"));
		}
		for (String query : List.of(
				"SELECT ?source ?predicate ?target WHERE { ?source ?predicate ?target . FILTER(isBlank(?source)) }",
				"CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o . FILTER(isBlank(?s)) }")) {
			var response = new MockHttpServletResponse();
			servlet.service(sparqlPost(query), response);
			assertThat(response.getStatus()).isEqualTo(200);
			var rows = JSON_MAPPER.readTree(response.getContentAsString()).path("results").path("bindings");
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0).path("source").path("rdf4j:reference").asBoolean()).as(query).isTrue();
			assertThat(rows.get(0).path("target").path("rdf4j:reference").asBoolean()).as(query).isTrue();
		}
	}

	@Test
	void tripleTermOnlyBlankNodesCarryReferencesButFactoryOnlyNodesDoNot() throws Exception {
		servlet.destroy();
		servlet = newServlet("graph-max-query-length", "1000");
		var factory = repository.getValueFactory();
		var stored = factory.createBNode("nested-stored");
		factory.createBNode("factory-only");
		try (var connection = repository.getConnection()) {
			connection.add(factory.createIRI("urn:reifier"), factory.createIRI("urn:reifies"),
					factory.createTripleTerm(factory.createIRI("urn:s"), factory.createIRI("urn:p"),
							factory.createTripleTerm(factory.createIRI("urn:t"), factory.createIRI("urn:q"), stored)));
		}
		var response = new MockHttpServletResponse();
		servlet.service(sparqlPost("SELECT ?source ?predicate ?target WHERE { VALUES ?source { <_:nested-stored> } "
				+ "BIND(<urn:p> AS ?predicate) BIND(<_:factory-only> AS ?target) }"), response);
		assertThat(response.getStatus()).isEqualTo(200);
		var row = JSON_MAPPER.readTree(response.getContentAsString()).path("results").path("bindings").get(0);
		assertThat(row.path("source").path("rdf4j:reference").asBoolean()).isTrue();
		assertThat(row.path("target").has("rdf4j:reference")).isFalse();
	}

